import {useEffect,useState,type ReactNode} from 'react';
import {Text,View} from 'react-native';
const P='11111111-1111-4111-8111-111111111111',U='22222222-2222-4222-8222-222222222222',I='33333333-3333-4333-8333-333333333333';
let offline=false,manager=false,conflict=false,revoked=false;let vehicles=[{id:I,unitId:U,plate:'34ABC123',type:'CAR',brand:'Örnek',model:null,color:null,status:'PENDING',reviewReason:null,version:1}];
let guests=[{id:I,hostUnitId:U,unitNumber:'12',spaceId:null,spaceCode:null,plate:'34MIS123',guestName:null,note:null,startsAt:new Date(Date.now()-3600000).toISOString(),endsAt:new Date(Date.now()+3600000).toISOString(),status:'PLANNED',arrivedAt:null as string|null,departedAt:null as string|null,version:1}];
const context=()=>({propertyId:P,propertyName:'Örnek Yönetim Alanı',unitId:manager?null:U,unitNumber:manager?null:'12',role:manager?'MANAGER':'TENANT'});
const change=()=>window.dispatchEvent(new Event('parking-fixture'));
export function Controls(){return <div style={{display:'flex',flexWrap:'wrap',gap:10,padding:12,font:'12px system-ui'}}><strong>OTOPARK06 · İzole native-web UI · Canlı API/auth yok</strong><button onClick={()=>{offline=!offline;change();}}>Bağlantı</button><button onClick={()=>{manager=!manager;change();}}>Rol</button><button onClick={()=>{conflict=true;}}>409</button><button onClick={()=>{revoked=true;change();}}>Yetkiyi kaldır</button></div>;}
export function useAuth(){const [,tick]=useState(0);useEffect(()=>{const fn=()=>tick(n=>n+1);window.addEventListener('parking-fixture',fn);return()=>window.removeEventListener('parking-fixture',fn);},[]);const c=context();return {state:'signedIn',selected:c,session:{userId:'fixture',contexts:[c]},offline,verifiedAt:Date.now(),choose:()=>{},parkingCache:async()=>{throw Error('Web fixture cache unavailable');},parkingRequest:async(url:string,body?:any)=>{
 await new Promise(r=>setTimeout(r,80));if(offline)throw Error();if(revoked)return new Response('{}',{status:403});
 if(body){if(conflict){conflict=false;return new Response(JSON.stringify({code:'BF_PARKING_SPACE_OCCUPIED'}),{status:409});}
  if(url.includes('/vehicles?')){const row={...body,id:crypto.randomUUID(),status:'PENDING',reviewReason:null,version:1};vehicles.push(row);return new Response(JSON.stringify(row));}
  if(url.includes('/guests?')){const row={...body,id:crypto.randomUUID(),unitNumber:'12',spaceCode:null,status:'PLANNED',arrivedAt:null,departedAt:null,version:1};guests.push(row);return new Response(JSON.stringify(row));}
  const action=url.split('?')[0].split('/').at(-1);const g=guests[0];g.status=action==='arrive'?'ARRIVED':action==='depart'?'DEPARTED':'CANCELLED';g.version++;if(action==='arrive')g.arrivedAt=new Date().toISOString();if(action==='depart')g.departedAt=new Date().toISOString();return new Response(JSON.stringify(g));
 }
 const value={userId:'fixture',contextKey:`${P}:${c.unitId??'-'}:${c.role}`,propertyId:P,unitId:c.unitId,role:c.role,asOf:new Date().toISOString(),page:1,vehicleTotal:manager?0:vehicles.length,allocationTotal:manager?0:1,guestTotal:manager?guests.length:0,unitTotal:manager?1:0,spaceTotal:0,vehicles:manager?[]:vehicles,allocations:manager?[]:[{id:I,spaceCode:'A01',startDate:'2026-10-01',endDate:null}],guests:manager?guests:[],units:manager?[{id:U,number:'12',buildingName:null}]:[],spaces:[],policyConfigured:true,guestMaxHours:24};return new Response(JSON.stringify(value));
 }};}
export const randomUUID=()=>crypto.randomUUID();
export const styles={text:{fontSize:15,lineHeight:23,color:'#102342'},muted:{fontSize:13,lineHeight:21,color:'#617187'},card:{padding:18,gap:12,borderRadius:20,borderWidth:1,borderColor:'#dbe3ef',backgroundColor:'#fff'},cardTitle:{fontSize:18,fontWeight:'700',color:'#102342'},button:{padding:15,minHeight:52,backgroundColor:'#2056bc',borderRadius:14,alignItems:'center'},buttonText:{fontSize:16,color:'#fff',fontWeight:'600'}} as const;
export function Icon({name}:{name:string}){return <Text aria-hidden style={{fontSize:20,color:'#2056bc'}}>{name.includes('car')?'▱':name.includes('check')?'✓':'◈'}</Text>;}
export function Screen({title,subtitle,children}:{title:string;subtitle?:string;children:ReactNode}){return <div style={{maxWidth:560,margin:'0 auto',paddingBottom:30}}><header style={{background:'#062641',color:'white',padding:24,borderRadius:'0 0 24px 24px',fontFamily:'system-ui'}}><strong>BuildingFlow</strong><h1>{title}</h1><p>{subtitle}</p></header><main style={{padding:16}}>{children}</main></div>;}
export function Card({title,children}:{title:string;children:ReactNode}){return <View style={styles.card}><Text accessibilityRole="header" style={styles.cardTitle}>{title}</Text>{children}</View>;}
